14	pub const DEFAULT_LIMIT: usize = 50;
15	/// Cap on rendered ambiguous-name candidates (R6f: common method names could
16	/// print megabytes; the total count still travels in the error).
17	pub const MAX_AMBIGUOUS_CANDIDATES: usize = 50;
18	pub const MAX_LIMIT: usize = 10_000;
