20	/// Permanent honesty caveat for `kg dead` (Amendment 5): candidates, not proof.
21	const DEAD_CAVEAT: &str =
22	    "kg: dead-code candidates — dynamic dispatch, entry points, star imports, module-level imports, and external callers are not proven absent";
23	
24	/// Permanent honesty caveat for `kg clones` (Amendment 12d): candidates, not proof.
25	const CLONES_CAVEAT: &str =
26	    "kg: clone candidates — normalized-text equality, not proof of semantic duplication";
27	
28	/// Permanent honesty caveat for `kg path` (Amendment 13): resolved static
29	/// edges only; dynamic dispatch may hide paths.
30	const PATH_CAVEAT: &str = "kg: path — resolved static edges only; dynamic dispatch may hide paths";
31	
32	/// Permanent honesty caveat for `kg context` (Amendment 17).
33	const CONTEXT_CAVEAT: &str =
34	    "kg: context — resolved static edges only; dynamic dispatch may hide callers or callees";
35	
36	/// Permanent honesty caveat for `kg implementers` (Amendment 19).
37	const IMPLEMENTERS_CAVEAT: &str = "kg: implementers — resolved static inherits edges only; dynamic inheritance and cross-file impls are omitted";
38	
39	/// `impact` caveats (Amendment 19): the default calls-only shape stays
40	/// byte-identical; the extended shapes state their static-edge limit.
41	const IMPACT_EDGES_CAVEAT: &str =
42	    "kg: impact — resolved static edges only; unresolved imports/inherits are omitted";
43	const IMPACT_CALLS_CAVEAT: &str =
44	    "kg: impact — resolved static call edges only; dynamic dispatch may hide dependents";
45	
46	/// One import statement is one site even when it resolves to both a module and
47	/// a symbol edge; every non-import edge remains an individual site.
48	const IMPACT_SITE_KEY: &str =
49	    "CASE WHEN e.kind = 'imports' THEN 'i:' || ss.id || ':' || e.site_line ELSE 'e:' || e.id END";
50	
51	/// `kg imports` caveat (Amendment 19): outbound resolved imports only.
52	const IMPORTS_CAVEAT: &str =
53	    "kg: imports — resolved static imports only; external and unresolved imports are omitted";
54	
55	/// `kg tests` caveat (Amendment 19): static candidates only.
56	const TESTS_CAVEAT: &str = "kg: test candidates — static resolved call edges only; Rust #[test] names outside test_*, TS describe/it callbacks, fixtures, and indirect tests may be missed";
57	
58	fn is_test_symbol_name(name: &str) -> bool {
59	    name.starts_with("test_")
60	        || (name.starts_with("test") && name.chars().nth(4).is_some_and(|c| c.is_ascii_uppercase()))
61	}
