63	/// Bounded top-test collector: `seen` counts every distinct reachable test
64	/// symbol, while `heap` keeps only the first `limit` rows in output order.
65	struct TestTop {
66	    limit: usize,
67	    seen: HashSet<i64>,
68	    heap: BinaryHeap<(String, i64, String)>,
69	}
70	
71	impl TestTop {
72	    fn new(limit: usize) -> Self {
73	        Self {
74	            limit,
75	            seen: HashSet::new(),
76	            heap: BinaryHeap::new(),
77	        }
78	    }
79	
80	    fn insert(&mut self, id: i64, path: String, line: i64, qualname: String) {
81	        if !self.seen.insert(id) {
82	            return;
83	        }
84	        let record = (path, line, qualname);
85	        if self.heap.len() < self.limit {
86	            self.heap.push(record);
87	        } else if self.heap.peek().is_some_and(|max| record < *max) {
88	            self.heap.pop();
89	            self.heap.push(record);
90	        }
91	    }
92	
93	    fn is_empty(&self) -> bool {
94	        self.seen.is_empty()
95	    }
96	
97	    fn finish(mut self) -> (usize, Vec<(String, i64, String)>) {
98	        let total = self.seen.len();
99	        let mut records = std::mem::take(&mut self.heap).into_vec();
100	        records.sort_by(|a, b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)).then(a.2.cmp(&b.2)));
101	        (total, records)
102	    }
103	}
