105	pub fn test_impact(
106	    conn: &Connection,
107	    root: &Path,
108	    target: &str,
109	    depth: usize,
110	    limit: usize,
111	) -> Result<QueryOutput> {
112	    let limit = clamp_limit(limit)?;
113	    let depth = depth.clamp(1, 10);
114	    let target = target.trim_start_matches("./").trim_end_matches('/');
115	    let file_exists: bool = conn
116	        .query_row(
117	            "SELECT COUNT(*) FROM files WHERE path = ?1",
118	            [target],
119	            |r| r.get(0),
120	        )
121	        .map(|c: i64| c > 0)?;
122	    let seed_ids: Vec<i64> = if file_exists {
123	        let mut stmt = conn.prepare(
124	            "SELECT s.id FROM symbols s JOIN files f ON f.id = s.file_id WHERE f.path = ?1",
125	        )?;
126	        let rows = stmt.query_map([target], |r| r.get(0))?;
127	        rows.collect::<std::result::Result<_, _>>()?
128	    } else {
129	        let (ids, cands) = target_ids(conn, target)?;
130	        if ids.is_empty() {
131	            return Err(KgError::NoResults(format!(
132	                "symbol '{target}' not in index"
133	            )));
134	        }
135	        if cands.len() > 1 {
136	            return Err(KgError::Ambiguous {
137	                name: target.to_string(),
138	                total: ids.len(),
139	                candidates: cands,
140	                role: None,
141	            });
142	        }
143	        ids
144	    };
145	    let seed_set: HashSet<i64> = seed_ids.iter().copied().collect();
146	    let mut visited: HashSet<i64> = seed_set.clone();
147	    let mut current = seed_ids;
148	    let mut tests = TestTop::new(limit);
149	    let mut truncated = false;
150	    for d in 1..=depth {
151	        if current.is_empty() {
152	            break;
153	        }
154	        let mut next = Vec::new();
155	        for chunk in current.chunks(500) {
156	            let placeholders = chunk.iter().map(|_| "?").collect::<Vec<_>>().join(",");
157	            let sql = format!(
158	                "SELECT DISTINCT e.src_id, s.name, s.kind, f.path, s.line_start, s.qualname
159	                 FROM edges e JOIN symbols s ON s.id = e.src_id JOIN files f ON f.id = s.file_id
160	                 WHERE e.dst_id IN ({placeholders}) AND e.kind = 'calls'
161	                 ORDER BY f.path, s.line_start, s.qualname"
162	            );
163	            let mut stmt = conn.prepare(&sql)?;
164	            let params: Vec<rusqlite::types::Value> = chunk
165	                .iter()
166	                .map(|i| rusqlite::types::Value::from(*i))
167	                .collect();
168	            let rows = stmt.query_map(rusqlite::params_from_iter(params.iter()), |r| {
169	                Ok((
170	                    r.get::<_, i64>(0)?,
171	                    r.get::<_, String>(1)?,
172	                    r.get::<_, String>(2)?,
173	                    r.get::<_, String>(3)?,
174	                    r.get::<_, i64>(4)?,
175	                    r.get::<_, String>(5)?,
176	                ))
177	            })?;
178	            for row in rows {
179	                let (id, name, kind, path, line, qualname) = row?;
180	                if !seed_set.contains(&id)
181	                    && matches!(kind.as_str(), "function" | "method")
182	                    && is_test_symbol_name(&name)
183	                {
184	                    tests.insert(id, path, line, qualname);
185	                }
186	                if visited.insert(id) {
187	                    next.push(id);
188	                }
189	            }
190	        }
191	        if d == depth && !next.is_empty() {
192	            truncated = true;
193	        }
194	        current = next;
195	    }
196	    if tests.is_empty() {
197	        return Err(if truncated {
198	            KgError::NoResultsCaveated {
199	                caveat: TESTS_CAVEAT,
200	                detail: format!(
201	                    "no test candidate within depth {depth}; a longer route may exist (static call edges only)"
202	                ),
203	            }
204	        } else {
205	            KgError::NoResultsCaveated {
206	                caveat: TESTS_CAVEAT,
207	                detail: "0 test candidates found (static call edges only)".to_string(),
208	            }
209	        });
210	    }
211	    let (total, rows) = tests.finish();
212	    let pointers: Vec<Pointer> = rows
213	        .into_iter()
214	        .map(|(file, line, qualname)| Pointer {
215	            file,
216	            line,
217	            tag: "",
218	            detail: qualname,
219	        })
220	        .collect();
221	    let mut out = collect_output(
222	        conn,
223	        root,
224	        "",
225	        pointers.into_iter().map(Ok),
226	        limit,
227	        "0 test candidates found (static call edges only)",
228	        Some(total),
229	    )?;
230	    let mut header = TESTS_CAVEAT.to_string();
231	    if let Some(stale) = out.header.take() {
232	        header.push('\n');
233	        header.push_str(&stale);
234	    }
235	    if truncated {
236	        header.push_str(&format!(
237	            "\nkg: depth cap {depth} reached; deeper tests may exist"
238	        ));
239	    }
240	    out.header = Some(header);
241	    Ok(out)
242	}
