244	pub fn imports(conn: &Connection, root: &Path, file: &str, limit: usize) -> Result<QueryOutput> {
245	    let limit = clamp_limit(limit)?;
246	    let rel = file.trim_start_matches("./").to_string();
247	    let exists: bool = conn
248	        .query_row("SELECT COUNT(*) FROM files WHERE path = ?1", [&rel], |r| {
249	            r.get(0)
250	        })
251	        .map(|c: i64| c > 0)?;
252	    if !exists {
253	        return Err(KgError::NoResults(format!("path '{file}' not indexed")));
254	    }
255	    let total: usize = conn.query_row(
256	        "SELECT COUNT(*) FROM edges e
257	         JOIN symbols s ON s.id = e.src_id JOIN files f ON f.id = s.file_id
258	         WHERE f.path = ?1 AND e.kind = 'imports'",
259	        [&rel],
260	        |r| r.get::<_, i64>(0),
261	    )? as usize;
262	    if total == 0 {
263	        return Err(KgError::NoResultsCaveated {
264	            caveat: IMPORTS_CAVEAT,
265	            detail: "0 imports found (external and unresolved imports are omitted)".to_string(),
266	        });
267	    }
268	    let sql = format!(
269	        "SELECT e.site_line, e.dst_name FROM edges e
270	         JOIN symbols s ON s.id = e.src_id JOIN files f ON f.id = s.file_id
271	         WHERE f.path = ?1 AND e.kind = 'imports'
272	         ORDER BY e.site_line, e.dst_name LIMIT {limit}"
273	    );
274	    let mut stmt = conn.prepare(&sql)?;
275	    let rows = stmt.query_map([&rel], |r| {
276	        Ok(Pointer {
277	            file: rel.clone(),
278	            line: r.get(0)?,
279	            tag: "",
280	            detail: r.get(1)?,
281	        })
282	    })?;
283	    let mut out = collect_output(
284	        conn,
285	        root,
286	        &rel,
287	        rows,
288	        limit,
289	        "0 imports found (external and unresolved imports are omitted)",
290	        Some(total),
291	    )?;
292	    out.header = Some(match out.header.take() {
293	        Some(stale) => format!("{IMPORTS_CAVEAT}\n{stale}"),
294	        None => IMPORTS_CAVEAT.to_string(),
295	    });
296	    Ok(out)
297	}
