299	/// One resolved candidate: (path, line, qualname).
300	pub type Candidate = (String, i64, String);
301	
302	/// One symbol row with metrics: (kind, qualname, line, signature,
303	/// cyclomatic, branches, nesting, effective_loc). Amendment 19.
304	type SymbolRow = (String, String, i64, String, i64, i64, i64, i64);
