306	/// One BFS level's out-edges grouped per source: `(dst qualname, dst path,
307	/// site_line, dst id)` sorted by the pinned neighbor key (`path` is the
308	/// destination file). Amendment 13.
309	type LevelEdges = std::collections::HashMap<i64, Vec<(String, String, i64, i64)>>;
