311	pub struct Pointer {
312	    pub file: String,
313	    pub line: i64,
314	    pub tag: &'static str, // "" or " [ambiguous]"
315	    /// Optional trailing detail rendered after the tag (search hits carry the
316	    /// qualname here, Amendment 12b; empty for call-edge pointers).
317	    pub detail: String,
318	}
319	
320	impl Pointer {
321	    pub fn render(&self) -> String {
322	        if self.detail.is_empty() {
323	            format!("{}:{}{}", self.file, self.line, self.tag)
324	        } else {
325	            format!(
326	                "{}:{}{} {}",
327	                self.file,
328	                self.line,
329	                self.tag.trim_start(),
330	                self.detail
331	            )
332	        }
333	    }
334	}
