336	pub struct QueryOutput {
337	    pub header: Option<String>,
338	    pub pointers: Vec<Pointer>,
339	    pub shown: usize,
340	    pub total: usize,
341	    /// True when the staleness header fired on the displayed set (journal).
342	    pub stale: bool,
343	}
