345	pub fn clamp_limit(limit: usize) -> Result<usize> {
346	    if limit == 0 {
347	        return Err(KgError::Usage("--limit must be >= 1".to_string()));
348	    }
349	    Ok(limit.min(MAX_LIMIT))
350	}
