352	/// Resolve the query name to target symbol ids. Multiple distinct symbols ->
353	/// exit 2 with a `path:line qualname` candidate list on stdout (CUJ4).
354	fn target_ids(conn: &Connection, name: &str) -> Result<(Vec<i64>, Vec<Candidate>)> {
355	    let mut stmt = conn.prepare(
356	        "SELECT s.id, s.qualname, s.name, f.path, s.line_start, s.kind
357	         FROM symbols s JOIN files f ON f.id = s.file_id
358	         WHERE s.name = ?1 OR s.qualname = ?1
359	         ORDER BY s.qualname, f.path",
360	    )?;
361	    let rows = stmt.query_map(rusqlite::params![name], |r| {
362	        Ok((
363	            r.get::<_, i64>(0)?,
364	            r.get::<_, String>(1)?,
365	            r.get::<_, String>(2)?,
366	            r.get::<_, String>(3)?,
367	            r.get::<_, i64>(4)?,
368	            r.get::<_, String>(5)?,
369	        ))
370	    })?;
371	    let all: Vec<_> = rows.collect::<std::result::Result<_, _>>()?;
372	    // A module shares the bare name of classes/functions (`button` vs
373	    // `Button`); when a callable candidate exists, module symbols must not
374	    // create a false ambiguity (R7 F1).
375	    let has_callable = all.iter().any(|r| r.5 != "module");
376	    let mut ids = Vec::new();
377	    let mut cands = Vec::new();
378	    let mut seen_ids: std::collections::HashSet<i64> = Default::default();
379	    for row in all {
380	        let (id, qualname, sname, path, line, kind) = row;
381	        if has_callable && kind == "module" {
382	            continue;
383	        }
384	        // Dedupe by id: a symbol whose bare name equals its qualname matches
385	        // both WHERE branches and must not create a false ambiguity. O(1)
386	        // membership (R6f: a Vec::contains scan was quadratic).
387	        if seen_ids.insert(id) {
388	            ids.push(id);
389	            // Render cap only (R6f): the error carries `total` separately and
390	            // the caller prints at most MAX_AMBIGUOUS_CANDIDATES lines.
391	            if cands.len() < MAX_AMBIGUOUS_CANDIDATES {
392	                cands.push((path, line, qualname));
393	            }
394	        }
395	        let _ = sname;
396	    }
397	    Ok((ids, cands))
398	}
