468	pub fn implementers(
469	    conn: &Connection,
470	    root: &Path,
471	    name: &str,
472	    limit: usize,
473	) -> Result<QueryOutput> {
474	    let limit = clamp_limit(limit)?;
475	    let (ids, cands) = target_ids(conn, name)?;
476	    if ids.is_empty() {
477	        return Err(KgError::NoResults(format!("symbol '{name}' not in index")));
478	    }
479	    if cands.len() > 1 {
480	        return Err(KgError::Ambiguous {
481	            name: name.to_string(),
482	            total: ids.len(),
483	            candidates: cands,
484	            role: None,
485	        });
486	    }
487	    let placeholders = ids.iter().map(|_| "?").collect::<Vec<_>>().join(",");
488	    let params: Vec<rusqlite::types::Value> = ids
489	        .iter()
490	        .map(|i| rusqlite::types::Value::from(*i))
491	        .collect();
492	    let total: usize = conn.query_row(
493	        &format!(
494	            "SELECT COUNT(DISTINCT e.src_id) FROM edges e
495	             WHERE e.dst_id IN ({placeholders}) AND e.kind = 'inherits'"
496	        ),
497	        rusqlite::params_from_iter(params.iter()),
498	        |r| r.get::<_, i64>(0),
499	    )? as usize;
500	    let sql = format!(
501	        "SELECT DISTINCT f.path, s.line_start, s.qualname
502	         FROM edges e
503	         JOIN symbols s ON s.id = e.src_id
504	         JOIN files f ON f.id = s.file_id
505	         WHERE e.dst_id IN ({placeholders}) AND e.kind = 'inherits'
506	         ORDER BY f.path, s.line_start, s.qualname LIMIT {limit}"
507	    );
508	    let mut stmt = conn.prepare(&sql)?;
509	    let rows = stmt.query_map(rusqlite::params_from_iter(params.iter()), |r| {
510	        Ok(Pointer {
511	            file: r.get(0)?,
512	            line: r.get(1)?,
513	            tag: "",
514	            detail: r.get(2)?,
515	        })
516	    })?;
517	    if total == 0 {
518	        return Err(KgError::NoResultsCaveated {
519	            caveat: IMPLEMENTERS_CAVEAT,
520	            detail: "0 implementers found (resolved inherits edges only)".to_string(),
521	        });
522	    }
523	    let mut out = collect_output(
524	        conn,
525	        root,
526	        name,
527	        rows,
528	        limit,
529	        "0 implementers found (resolved inherits edges only)",
530	        Some(total),
531	    )?;
532	    out.header = Some(match out.header.take() {
533	        Some(stale) => format!("{IMPLEMENTERS_CAVEAT}\n{stale}"),
534	        None => IMPLEMENTERS_CAVEAT.to_string(),
535	    });
536	    Ok(out)
537	}
