539	pub fn callees(
540	    conn: &Connection,
541	    root: &Path,
542	    name: &str,
543	    limit: usize,
544	    depth: usize,
545	) -> Result<QueryOutput> {
546	    let limit = clamp_limit(limit)?;
547	    let depth = depth.clamp(1, 10);
548	    let (ids, cands) = target_ids(conn, name)?;
549	    if ids.is_empty() {
550	        return Err(KgError::NoResults(format!("symbol '{name}' not in index")));
551	    }
552	    if cands.len() > 1 {
553	        return Err(KgError::Ambiguous {
554	            name: name.to_string(),
555	            total: ids.len(),
556	            candidates: cands,
557	            role: None,
558	        });
559	    }
560	    // Callee pointer: the callee's definition line. AMBIGUOUS edges have no
561	    // dst symbol; they surface as the call site itself with the ambiguous tag.
562	    // depth > 1: recursive closure over call edges from the reached set.
563	    let total_opt: Option<usize>;
564	    let mut params: Vec<rusqlite::types::Value> = ids
565	        .iter()
566	        .map(|i| rusqlite::types::Value::from(*i))
567	        .collect();
568	    let sql: String = if depth == 1 {
569	        let placeholders = ids.iter().map(|_| "?").collect::<Vec<_>>().join(",");
570	        let count_sql = format!(
571	            "SELECT COUNT(DISTINCT COALESCE(ds.id, -(1000000 + e.id)))
572	             FROM edges e LEFT JOIN symbols ds ON ds.id = e.dst_id
573	             WHERE e.src_id IN ({placeholders}) AND e.kind = 'calls'"
574	        );
575	        total_opt = Some(conn.query_row(
576	            &count_sql,
577	            rusqlite::params_from_iter(params.iter()),
578	            |r| r.get::<_, i64>(0),
579	        )? as usize);
580	        format!(
581	            "SELECT MIN(COALESCE(ds.line_start, e.site_line)) AS line,
582	                MAX(e.confidence) AS confidence,
583	                MAX(COALESCE(df.path, sf.path)) AS path,
584	                COALESCE(ds.qualname, '') AS qn
585	         FROM edges e
586	         JOIN symbols s ON s.id = e.src_id JOIN files sf ON sf.id = s.file_id
587	         LEFT JOIN symbols ds ON ds.id = e.dst_id
588	         LEFT JOIN files df ON df.id = ds.file_id
589	         WHERE e.src_id IN ({placeholders}) AND e.kind = 'calls'
590	         GROUP BY COALESCE(ds.id, -(1000000 + e.id))
591	         ORDER BY path, line LIMIT {limit}"
592	        )
593	    } else {
594	        let seed = ids.iter().map(|_| "?").collect::<Vec<_>>().join(",");
595	        let cte = format!(
596	            "WITH RECURSIVE reach(sym, d) AS (
597	             SELECT id, 0 FROM symbols WHERE id IN ({seed})
598	             UNION
599	             SELECT e.dst_id, r.d + 1 FROM edges e JOIN reach r ON e.src_id = r.sym
600	             WHERE e.kind = 'calls' AND e.dst_id IS NOT NULL AND r.d < ?{d}
601	         )",
602	            d = 1 + ids.len()
603	        );
604	        let select = format!(
605	            "SELECT DISTINCT COALESCE(ds.line_start, e.site_line) AS line, e.confidence,
606	                COALESCE(df.path, sf.path) AS path, COALESCE(ds.qualname, '') AS qn
607	         FROM reach r
608	         -- CROSS JOIN + WHERE lets SQLite drive from the recursive set and
609	         -- use edges_src, instead of scanning the whole edge table (R7).
610	         CROSS JOIN edges e
611	         JOIN symbols ss ON ss.id = e.src_id JOIN files sf ON sf.id = ss.file_id
612	         LEFT JOIN symbols ds ON ds.id = e.dst_id
613	         LEFT JOIN files df ON df.id = ds.file_id
614	         WHERE e.src_id = r.sym AND e.kind = 'calls' AND r.d < ?{d2}",
615	            d2 = 2 + ids.len()
616	        );
617	        params.push(rusqlite::types::Value::from(depth as i64));
618	        params.push(rusqlite::types::Value::from(depth as i64));
619	        let count_sql = format!("{cte} SELECT COUNT(*) FROM ({select})");
620	        total_opt = Some(conn.query_row(
621	            &count_sql,
622	            rusqlite::params_from_iter(params.iter()),
623	            |r| r.get::<_, i64>(0),
624	        )? as usize);
625	        // Bounded materialization (R6 round-2): the closure result is
626	        // counted above and fetched with LIMIT, never fully collected.
627	        format!("{cte} {select} ORDER BY path, line LIMIT {limit}")
628	    };
629	    let mut stmt = conn.prepare(&sql)?;
630	    let rows = stmt.query_map(rusqlite::params_from_iter(params.iter()), |r| {
631	        let line: i64 = r.get(0)?;
632	        let conf: String = r.get(1)?;
633	        let path: String = r.get(2)?;
634	        Ok(Pointer {
635	            file: path,
636	            line,
637	            tag: if conf == "AMBIGUOUS" {
638	                " [ambiguous]"
639	            } else {
640	                ""
641	            },
642	            detail: r.get::<_, String>(3)?,
643	        })
644	    })?;
645	    collect_output(conn, root, name, rows, limit, "0 callees found", total_opt)
646	}
