792	/// `path` BFS outcome (Amendment 13): the found chain with its per-hop call
793	/// sites, or the two negative shapes the exit-1 contract distinguishes.
794	enum PathSearch {
795	    Found {
796	        chain_ids: Vec<i64>,
797	        hop_sites: Vec<i64>,
798	    },
799	    Exhausted,
800	    CapTruncated,
801	}
