803	/// Level-batched BFS over the resolved call-edge set (`kind = 'calls' AND
804	/// dst_id IS NOT NULL`). One indexed query per frontier level (chunked at
805	/// 500 ids per the build's insert-batch precedent), not a full-corpus
806	/// adjacency load and not a query per node. Expansion order matches the
807	/// pinned discipline exactly: frontier nodes in FIFO discovery order, each
808	/// node's neighbors sorted by `(dst qualname, dst path, site_line)`,
809	/// multi-edges deduped by the visited guard (the first row per pair carries
810	/// the smallest `site_line`), parent = first discoverer. Worst case fetches
811	/// every resolved call edge once; typical queries touch only the reachable
812	/// subgraph.
813	fn path_bfs(conn: &Connection, from_id: i64, to_id: i64, depth: usize) -> Result<PathSearch> {
814	    let level_edges = |ids: &[i64]| -> Result<LevelEdges> {
815	        let mut grouped: LevelEdges = Default::default();
816	        for chunk in ids.chunks(500) {
817	            let placeholders = chunk.iter().map(|_| "?").collect::<Vec<_>>().join(",");
818	            let sql = format!(
819	                "SELECT e.src_id, e.dst_id, e.site_line, ds.qualname, df.path
820	                 FROM edges e
821	                 JOIN symbols ds ON ds.id = e.dst_id
822	                 JOIN files df ON df.id = ds.file_id
823	                 WHERE e.kind = 'calls' AND e.dst_id IS NOT NULL
824	                   AND e.src_id IN ({placeholders})"
825	            );
826	            let mut stmt = conn.prepare(&sql)?;
827	            let params: Vec<rusqlite::types::Value> = chunk
828	                .iter()
829	                .map(|i| rusqlite::types::Value::from(*i))
830	                .collect();
831	            let rows = stmt.query_map(rusqlite::params_from_iter(params.iter()), |r| {
832	                Ok((
833	                    r.get::<_, i64>(0)?,
834	                    r.get::<_, i64>(1)?,
835	                    r.get::<_, i64>(2)?,
836	                    r.get::<_, String>(3)?,
837	                    r.get::<_, String>(4)?,
838	                ))
839	            })?;
840	            for r in rows {
841	                let (src, dst, site, qn, fpath) = r?;
842	                grouped.entry(src).or_default().push((qn, fpath, site, dst));
843	            }
844	        }
845	        for neighbors in grouped.values_mut() {
846	            neighbors.sort();
847	        }
848	        Ok(grouped)
849	    };
850	    let mut parent: std::collections::HashMap<i64, (i64, i64)> = Default::default();
851	    let mut visited: std::collections::HashSet<i64> = Default::default();
852	    let mut frontier: Vec<i64> = vec![from_id];
853	    visited.insert(from_id);
854	    let mut found = false;
855	    let mut d = 0usize;
856	    while !found && !frontier.is_empty() && d < depth {
857	        let grouped = level_edges(&frontier)?;
858	        let mut next: Vec<i64> = Vec::new();
859	        for &v in &frontier {
860	            let Some(neighbors) = grouped.get(&v) else {
861	                continue;
862	            };
863	            // Sorted by (dst qualname, dst path, site_line): the first
864	            // unvisited row per destination carries the smallest site_line.
865	            for (_, _, site, w) in neighbors {
866	                if visited.contains(w) {
867	                    continue;
868	                }
869	                visited.insert(*w);
870	                parent.insert(*w, (v, *site));
871	                if *w == to_id {
872	                    found = true;
873	                    break;
874	                }
875	                next.push(*w);
876	            }
877	            if found {
878	                break;
879	            }
880	        }
881	        frontier = next;
882	        d += 1;
883	    }
884	    if found {
885	        // Walk parents back to the seed: chain node ids + per-hop call sites.
886	        let mut chain_ids: Vec<i64> = vec![to_id];
887	        let mut hop_sites: Vec<i64> = Vec::new();
888	        let mut cur = to_id;
889	        while cur != from_id {
890	            let Some(&(p, site)) = parent.get(&cur) else {
891	                return Err(KgError::Internal(
892	                    "path reconstruction lost a parent link".to_string(),
893	                ));
894	            };
895	            hop_sites.push(site);
896	            chain_ids.push(p);
897	            cur = p;
898	        }
899	        chain_ids.reverse();
900	        hop_sites.reverse();
901	        return Ok(PathSearch::Found {
902	            chain_ids,
903	            hop_sites,
904	        });
905	    }
906	    if !frontier.is_empty() && d == depth {
907	        // Cap-truncation probe: an unvisited out-neighbor of any node at the
908	        // maximum distance means a longer path may exist.
909	        let grouped = level_edges(&frontier)?;
910	        for neighbors in grouped.values() {
911	            if neighbors.iter().any(|(_, _, _, w)| !visited.contains(w)) {
912	                return Ok(PathSearch::CapTruncated);
913	            }
914	        }
915	    }
916	    Ok(PathSearch::Exhausted)
917	}
