919	/// One-call symbol context (Amendment 17): definition line with signature,
920	/// direct callers, and direct callees — replaces composing callers/callees/
921	/// symbols for "what does this symbol do and who uses it" questions.
922	pub fn context(conn: &Connection, root: &Path, name: &str, limit: usize) -> Result<Vec<String>> {
923	    // The CLI documents max 50 per section; clamp here so MCP callers cannot
924	    // bypass the contract.
925	    let limit = clamp_limit(limit)?.min(50);
926	    let (ids, cands) = target_ids(conn, name)?;
927	    if ids.is_empty() {
928	        return Err(KgError::NoResults(format!("symbol '{name}' not in index")));
929	    }
930	    if cands.len() > 1 {
931	        return Err(KgError::Ambiguous {
932	            name: name.to_string(),
933	            total: ids.len(),
934	            candidates: cands,
935	            role: None,
936	        });
937	    }
938	    let id = ids[0];
939	    let def_sql = "SELECT f.path, s.line_start, s.line_end, s.kind, s.qualname, s.signature
940	                   FROM symbols s JOIN files f ON f.id = s.file_id WHERE s.id = ?1";
941	    let (def_path, def_line, def_end, kind, qualname, signature): (
942	        String,
943	        i64,
944	        i64,
945	        String,
946	        String,
947	        String,
948	    ) = conn.query_row(def_sql, [id], |r| {
949	        Ok((
950	            r.get(0)?,
951	            r.get(1)?,
952	            r.get(2)?,
953	            r.get(3)?,
954	            r.get(4)?,
955	            r.get(5)?,
956	        ))
957	    })?;
958	    let callers_total: usize = conn.query_row(
959	        "SELECT COUNT(*) FROM edges e WHERE e.dst_id = ?1 AND e.kind = 'calls'",
960	        [id],
961	        |r| r.get::<_, i64>(0),
962	    )? as usize;
963	    let mut stmt = conn.prepare(
964	        "SELECT e.site_line, f.path, s.qualname
965	         FROM edges e JOIN symbols s ON s.id = e.src_id JOIN files f ON f.id = s.file_id
966	         WHERE e.dst_id = ?1 AND e.kind = 'calls'
967	         ORDER BY f.path, e.site_line LIMIT ?2",
968	    )?;
969	    let callers: Vec<(String, i64, String)> = stmt
970	        .query_map(rusqlite::params![id, limit as i64], |r| {
971	            Ok((
972	                r.get::<_, String>(1)?,
973	                r.get::<_, i64>(0)?,
974	                r.get::<_, String>(2)?,
975	            ))
976	        })?
977	        .collect::<std::result::Result<Vec<_>, _>>()?;
978	    let callees_total: usize = conn.query_row(
979	        "SELECT COUNT(DISTINCT COALESCE(ds.id, -(1000000 + e.id)))
980	         FROM edges e LEFT JOIN symbols ds ON ds.id = e.dst_id
981	         WHERE e.src_id = ?1 AND e.kind = 'calls'",
982	        [id],
983	        |r| r.get::<_, i64>(0),
984	    )? as usize;
985	    let mut stmt = conn.prepare(
986	        "SELECT MIN(COALESCE(ds.line_start, e.site_line)) AS line,
987	                MAX(COALESCE(df.path, sf.path)) AS path,
988	                COALESCE(ds.qualname, e.dst_name) AS qn,
989	                MAX(e.confidence) AS conf
990	         FROM edges e
991	         JOIN symbols s ON s.id = e.src_id JOIN files sf ON sf.id = s.file_id
992	         LEFT JOIN symbols ds ON ds.id = e.dst_id
993	         LEFT JOIN files df ON df.id = ds.file_id
994	         WHERE e.src_id = ?1 AND e.kind = 'calls'
995	         GROUP BY COALESCE(ds.id, -(1000000 + e.id))
996	         ORDER BY path, line LIMIT ?2",
997	    )?;
998	    let callees: Vec<(String, i64, String, String)> = stmt
999	        .query_map(rusqlite::params![id, limit as i64], |r| {
1000	            Ok((
1001	                r.get::<_, String>(1)?,
1002	                r.get::<_, i64>(0)?,
1003	                r.get::<_, String>(2)?,
1004	                r.get::<_, String>(3)?,
1005	            ))
1006	        })?
1007	        .collect::<std::result::Result<Vec<_>, _>>()?;
1008	    // Staleness over the displayed set (definition + shown callers/callees).
1009	    let mut files: BTreeSet<&String> = BTreeSet::new();
1010	    files.insert(&def_path);
1011	    for (p, _, _) in &callers {
1012	        files.insert(p);
1013	    }
1014	    for (p, _, _, _) in &callees {
1015	        files.insert(p);
1016	    }
1017	    let n_files = files.len();
1018	    let mut changed = 0usize;
1019	    for f in &files {
1020	        if file_changed(conn, root, f) {
1021	            changed += 1;
1022	        }
1023	    }
1024	    let stale = changed > 0;
1025	    // Payload pointers must be byte-identical to the stdout data lines
1026	    // (Amendment 10/G11), including the identity suffix added in R7.
1027	    let caller_lines: Vec<String> = callers
1028	        .iter()
1029	        .map(|(p, l, qn)| format!("{p}:{l} {qn}"))
1030	        .collect();
1031	    let callee_lines: Vec<String> = callees
1032	        .iter()
1033	        .map(|(p, l, qn, conf)| {
1034	            let tag = if conf == "AMBIGUOUS" {
1035	                " [ambiguous]"
1036	            } else {
1037	                ""
1038	            };
1039	            format!("{p}:{l}{tag} {qn}")
1040	        })
1041	        .collect();
1042	    let mut pointers = caller_lines.clone();
1043	    pointers.extend(callee_lines.iter().cloned());
1044	    let total = callers_total + callees_total;
1045	    let shown = pointers.len();
1046	    let built_at = db::meta_get(conn, "built_at")
1047	        .and_then(|v| v.parse().ok())
1048	        .unwrap_or(0);
1049	    let source_rev = db::meta_get(conn, "source_rev").unwrap_or_default();
1050	    crate::journal::record_payload(name, &pointers, stale, shown, total, built_at, &source_rev);
1051	    crate::journal::record_result(shown, shown, total, stale, 0);
1052	    let mut out = vec![CONTEXT_CAVEAT.to_string()];
1053	    if stale {
1054	        out.push(format!(
1055	            "kg: {changed} of {n_files} result files changed since build — run kg build"
1056	        ));
1057	    }
1058	    let sig = if signature.is_empty() {
1059	        String::new()
1060	    } else {
1061	        format!(" {signature}")
1062	    };
1063	    out.push(format!(
1064	        "{def_path}:{def_line}-{def_end} {kind} {qualname}{sig}"
1065	    ));
1066	    out.push(format!(
1067	        "callers (showing {} of {}):",
1068	        callers.len(),
1069	        callers_total
1070	    ));
1071	    out.extend(caller_lines);
1072	    out.push(format!(
1073	        "callees (showing {} of {}):",
1074	        callees.len(),
1075	        callees_total
1076	    ));
1077	    out.extend(callee_lines);
1078	    Ok(out)
1079	}
