1462	fn direct_impact_level(
1463	    conn: &Connection,
1464	    rel: &str,
1465	    kind_sql: &str,
1466	    records: &mut ImpactTop,
1467	    depth: usize,
1468	) -> Result<(Vec<i64>, HashSet<i64>)> {
1469	    let sql = format!(
1470	        "SELECT e.src_id, e.site_line, e.kind, sf.path, ss.qualname, ss.kind
1471	         FROM edges e
1472	         JOIN symbols ds ON ds.id = e.dst_id JOIN files df ON df.id = ds.file_id
1473	         JOIN symbols ss ON ss.id = e.src_id JOIN files sf ON sf.id = ss.file_id
1474	         WHERE df.path = ?1 AND e.kind IN ({kind_sql})
1475	         ORDER BY sf.path, e.site_line, ss.qualname, e.id"
1476	    );
1477	    let mut stmt = conn.prepare(&sql)?;
1478	    let rows = stmt.query_map([rel], |r| {
1479	        Ok((
1480	            r.get::<_, i64>(0)?,
1481	            r.get::<_, i64>(1)?,
1482	            r.get::<_, String>(2)?,
1483	            r.get::<_, String>(3)?,
1484	            r.get::<_, String>(4)?,
1485	            r.get::<_, String>(5)?,
1486	        ))
1487	    })?;
1488	    let mut frontier = Vec::new();
1489	    let mut visited = HashSet::new();
1490	    let target_ids: Vec<i64> = {
1491	        let mut stmt = conn.prepare(
1492	            "SELECT s.id FROM symbols s JOIN files f ON f.id = s.file_id WHERE f.path = ?1",
1493	        )?;
1494	        let rows = stmt.query_map([rel], |r| r.get(0))?;
1495	        rows.collect::<std::result::Result<_, _>>()?
1496	    };
1497	    for id in target_ids {
1498	        visited.insert(id);
1499	    }
1500	    for r in rows {
1501	        let (src, line, kind, path, qn, src_kind) = r?;
1502	        records.insert(path, depth, line, kind, qn, src_kind);
1503	        if visited.insert(src) {
1504	            frontier.push(src);
1505	        }
1506	    }
1507	    Ok((frontier, visited))
1508	}
