1510	fn level_impact(
1511	    conn: &Connection,
1512	    frontier: &[i64],
1513	    visited: &mut HashSet<i64>,
1514	    kind_sql: &str,
1515	    records: &mut ImpactTop,
1516	    depth: usize,
1517	) -> Result<Vec<i64>> {
1518	    if frontier.is_empty() {
1519	        return Ok(Vec::new());
1520	    }
1521	    let mut next = Vec::new();
1522	    for chunk in frontier.chunks(500) {
1523	        let placeholders = chunk.iter().map(|_| "?").collect::<Vec<_>>().join(",");
1524	        let sql = format!(
1525	            "SELECT e.src_id, e.site_line, e.kind, sf.path, ss.qualname, ss.kind
1526	             FROM edges e
1527	             JOIN symbols ss ON ss.id = e.src_id JOIN files sf ON sf.id = ss.file_id
1528	             WHERE e.dst_id IN ({placeholders}) AND e.kind IN ({kind_sql})
1529	             ORDER BY sf.path, e.site_line, ss.qualname, e.id"
1530	        );
1531	        let mut stmt = conn.prepare(&sql)?;
1532	        let params: Vec<rusqlite::types::Value> = chunk
1533	            .iter()
1534	            .map(|i| rusqlite::types::Value::from(*i))
1535	            .collect();
1536	        let rows = stmt.query_map(rusqlite::params_from_iter(params.iter()), |r| {
1537	            Ok((
1538	                r.get::<_, i64>(0)?,
1539	                r.get::<_, i64>(1)?,
1540	                r.get::<_, String>(2)?,
1541	                r.get::<_, String>(3)?,
1542	                r.get::<_, String>(4)?,
1543	                r.get::<_, String>(5)?,
1544	            ))
1545	        })?;
1546	        for r in rows {
1547	            let (src, line, kind, path, qn, src_kind) = r?;
1548	            records.insert(path, depth, line, kind, qn, src_kind);
1549	            if visited.insert(src) {
1550	                next.push(src);
1551	            }
1552	        }
1553	    }
1554	    Ok(next)
1555	}
