1559	/// Bounded top-path collector for depth>1 impact. `seen` supplies the exact
1560	/// distinct-file count; `heap` keeps only the lexicographically smallest
1561	/// `limit` records, so the query never sorts the full closure.
1562	struct ImpactTop {
1563	    limit: usize,
1564	    seen: HashSet<String>,
1565	    heap: BinaryHeap<ImpactRecord>,
1566	}
1567	
1568	impl ImpactTop {
1569	    fn new(limit: usize) -> Self {
1570	        Self {
1571	            limit,
1572	            seen: HashSet::new(),
1573	            heap: BinaryHeap::new(),
1574	        }
1575	    }
1576	
1577	    fn insert(
1578	        &mut self,
1579	        path: String,
1580	        depth: usize,
1581	        line: i64,
1582	        kind: String,
1583	        qualname: String,
1584	        src_kind: String,
1585	    ) {
1586	        if !self.seen.insert(path.clone()) {
1587	            return;
1588	        }
1589	        let record = (path, depth, line, kind, qualname, src_kind);
1590	        if self.heap.len() < self.limit {
1591	            self.heap.push(record);
1592	        } else if self.heap.peek().is_some_and(|max| record.0 < max.0) {
1593	            self.heap.pop();
1594	            self.heap.push(record);
1595	        }
1596	    }
1597	
1598	    fn finish(mut self) -> (usize, Vec<ImpactRecord>) {
1599	        let total = self.seen.len();
1600	        let mut records = std::mem::take(&mut self.heap).into_vec();
1601	        records.sort_by(|a, b| a.0.cmp(&b.0));
1602	        (total, records)
1603	    }
1604	}
