1606	/// Dead-code candidates (Amendment 5): no resolved inbound calls edge and no
1607	/// AMBIGUOUS edge naming the symbol (qualname or bare name). Pointer contract;
1608	/// the caveat header is unconditional.
1609	pub fn dead(
1610	    conn: &Connection,
1611	    root: &Path,
1612	    limit: usize,
1613	    exclude_tests: bool,
1614	    exclude_generated: bool,
1615	    path: Option<&str>,
1616	) -> Result<QueryOutput> {
1617	    let limit = clamp_limit(limit)?;
1618	    if let Some(p) = path {
1619	        validate_path_scope(p, false)?;
1620	    }
1621	    // AMBIGUOUS suppression is per-symbol (R7): a bare-name ambiguous call
1622	    // suppresses only same-named symbols in the caller's own file; a symbol
1623	    // elsewhere with the same bare name is not presumed referenced.
1624	    // One materialized referenced-id set, shared by COUNT and the page query.
1625	    // The previous correlated NOT EXISTS re-scanned edges per candidate
1626	    // symbol (R7 review).
1627	    let referenced = "WITH trait_parents(qualname) AS MATERIALIZED (
1628	           SELECT DISTINCT qualname FROM symbols
1629	            WHERE kind IN ('trait', 'interface')
1630	       ),
1631	       referenced_ids(id) AS MATERIALIZED (
1632	           SELECT dst_id FROM edges
1633	            WHERE kind IN ('calls', 'imports', 'inherits') AND dst_id IS NOT NULL
1634	           UNION
1635	           SELECT s2.id FROM edges e
1636	             JOIN symbols s2 ON s2.qualname = e.dst_name
1637	            WHERE e.kind IN ('calls', 'imports', 'inherits')
1638	              AND e.confidence = 'AMBIGUOUS'
1639	           UNION
1640	           SELECT s2.id FROM edges e
1641	             JOIN symbols src ON src.id = e.src_id
1642	             JOIN symbols s2 ON s2.name = e.dst_name AND s2.file_id = src.file_id
1643	            WHERE e.kind IN ('calls', 'imports', 'inherits')
1644	              AND e.confidence = 'AMBIGUOUS'
1645	       )";
1646	    let mut predicate = "s.kind IN ('function', 'method', 'class', 'trait', 'interface')
1647	           AND s.id NOT IN (SELECT id FROM referenced_ids)
1648	           AND NOT EXISTS (
1649	               SELECT 1 FROM trait_parents tp
1650	                WHERE s.qualname >= tp.qualname || '.'
1651	                  AND s.qualname < tp.qualname || '/'
1652	           )"
1653	    .to_string();
1654	    if exclude_tests {
1655	        predicate.push_str(
1656	            " AND f.path NOT LIKE 'tests/%' AND f.path NOT LIKE '%/tests/%'
1657	              AND f.path NOT LIKE 'test/%' AND f.path NOT LIKE '%/test/%'
1658	              AND f.path NOT LIKE '__tests__/%' AND f.path NOT LIKE '%/__tests__/%'
1659	              AND f.path NOT LIKE 'test\\_%.py' ESCAPE '\\'
1660	              AND f.path NOT LIKE '%/test\\_%.py' ESCAPE '\\'
1661	              AND f.path NOT LIKE '%\\_test.py' ESCAPE '\\'
1662	              AND f.path NOT LIKE '%.test.%'
1663	              AND f.path NOT LIKE '%.spec.%'
1664	              AND f.path NOT LIKE '%\\_test.dart' ESCAPE '\\'
1665	              AND s.name NOT LIKE 'test\\_%' ESCAPE '\\'
1666	              AND s.name NOT GLOB 'test[A-Z]*'",
1667	        );
1668	    }
1669	    if exclude_generated {
1670	        predicate.push_str(" AND f.generated = 0");
1671	    }
1672	    if let Some(path) = path {
1673	        let escaped = path
1674	            .trim_start_matches("./")
1675	            .trim_end_matches('/')
1676	            .replace('\'', "''");
1677	        predicate.push_str(&format!(
1678	            " AND (f.path = '{escaped}' OR substr(f.path, 1, length('{escaped}') + 1) = '{escaped}' || '/')"
1679	        ));
1680	    }
1681	    let predicate = predicate.as_str();
1682	    let total: usize = conn.query_row(
1683	        &format!(
1684	            "{referenced} SELECT COUNT(*) FROM symbols s JOIN files f ON f.id = s.file_id WHERE {predicate}"
1685	        ),
1686	        [],
1687	        |r| r.get::<_, i64>(0),
1688	    )? as usize;
1689	    let sql = format!(
1690	        "{referenced} SELECT s.qualname, f.path, s.line_start
1691	         FROM symbols s JOIN files f ON f.id = s.file_id
1692	         WHERE {predicate}
1693	         ORDER BY f.path, s.line_start LIMIT {limit}"
1694	    );
1695	    let mut stmt = conn.prepare(&sql)?;
1696	    let rows = stmt.query_map([], |r| {
1697	        let path: String = r.get(1)?;
1698	        let line: i64 = r.get(2)?;
1699	        Ok(Pointer {
1700	            file: path,
1701	            line,
1702	            tag: "",
1703	            detail: String::new(),
1704	        })
1705	    })?;
1706	    if total == 0 {
1707	        return Err(KgError::NoResultsCaveated {
1708	            caveat: DEAD_CAVEAT,
1709	            detail: "0 dead-code candidates found".to_string(),
1710	        });
1711	    }
1712	    let mut out = collect_output(
1713	        conn,
1714	        root,
1715	        "",
1716	        rows,
1717	        limit,
1718	        "0 dead-code candidates found",
1719	        Some(total),
1720	    )?;
1721	    out.header = Some(match out.header.take() {
1722	        Some(stale) => format!("{DEAD_CAVEAT}\n{stale}"),
1723	        None => DEAD_CAVEAT.to_string(),
1724	    });
1725	    Ok(out)
1726	}
