1728	/// `kg complexity` (Amendment 19): per-symbol metric ranking.
1729	#[allow(clippy::too_many_arguments)] // CLI surface; a params struct adds no value here.
1730	pub fn complexity(
1731	    conn: &Connection,
1732	    root: &Path,
1733	    min_cyc: usize,
1734	    min_loc: usize,
1735	    min_branches: usize,
1736	    min_nest: usize,
1737	    path: Option<&str>,
1738	    exclude_generated: bool,
1739	    limit: usize,
1740	) -> Result<Vec<String>> {
1741	    let limit = clamp_limit(limit)?;
1742	    if let Some(p) = path {
1743	        validate_path_scope(p, false)?;
1744	    }
1745	    let mut gen_filter = file_path_scope_sql("s", path);
1746	    if exclude_generated {
1747	        gen_filter.push_str(" AND s.file_id NOT IN (SELECT id FROM files WHERE generated = 1)");
1748	    }
1749	    let default_filters = min_cyc <= 1
1750	        && min_loc == 0
1751	        && min_branches == 0
1752	        && min_nest == 0
1753	        && path.is_none()
1754	        && !exclude_generated;
1755	    let total: i64 = if default_filters {
1756	        db::meta_get(conn, "callable_count")
1757	            .and_then(|v| v.parse().ok())
1758	            .unwrap_or(0)
1759	    } else {
1760	        conn.query_row(
1761	            &format!(
1762	                "SELECT COUNT(*) FROM symbols s
1763	                 WHERE s.kind IN ('function','method')
1764	                   AND s.cyclomatic > 0 AND s.cyclomatic >= ?1
1765	                   AND s.effective_loc >= ?2 AND s.branches >= ?3
1766	                   AND s.nesting >= ?4 {gen_filter}"
1767	            ),
1768	            rusqlite::params![
1769	                min_cyc as i64,
1770	                min_loc as i64,
1771	                min_branches as i64,
1772	                min_nest as i64
1773	            ],
1774	            |r| r.get(0),
1775	        )?
1776	    };
1777	    if total == 0 {
1778	        return Err(KgError::NoResultsCaveated {
1779	            caveat: "kg: complexity — static AST proxy, not cognitive complexity; not comparable to hotspots/file cyclomatic",
1780	            detail: "0 symbols match the thresholds".to_string(),
1781	        });
1782	    }
1783	    let mut stmt = conn.prepare(&format!(
1784	        "SELECT s.file_path, s.line_start, s.cyclomatic, s.branches, s.nesting,
1785	                s.effective_loc, s.qualname
1786	         FROM symbols s INDEXED BY symbols_complexity_idx
1787	         WHERE s.kind IN ('function','method')
1788	           AND s.cyclomatic > 0 AND s.cyclomatic >= ?1 AND s.effective_loc >= ?2
1789	           AND s.branches >= ?3 AND s.nesting >= ?4 {gen_filter}
1790	         ORDER BY s.cyclomatic DESC, s.effective_loc DESC, s.qualname,
1791	                  s.file_path, s.line_start LIMIT {limit}"
1792	    ))?;
1793	    let rows: Vec<(String, String)> = stmt
1794	        .query_map(
1795	            rusqlite::params![
1796	                min_cyc as i64,
1797	                min_loc as i64,
1798	                min_branches as i64,
1799	                min_nest as i64
1800	            ],
1801	            |r| {
1802	                Ok((
1803	                    r.get::<_, String>(0)?,
1804	                    format!(
1805	                        "{}:{} cyc={} branches={} nest={} loc={} {}",
1806	                        r.get::<_, String>(0)?,
1807	                        r.get::<_, i64>(1)?,
1808	                        r.get::<_, i64>(2)?,
1809	                        r.get::<_, i64>(3)?,
1810	                        r.get::<_, i64>(4)?,
1811	                        r.get::<_, i64>(5)?,
1812	                        r.get::<_, String>(6)?
1813	                    ),
1814	                ))
1815	            },
1816	        )?
1817	        .collect::<std::result::Result<_, _>>()?;
1818	    let shown = rows.len().min(limit);
1819	    let displayed: BTreeSet<&str> = rows.iter().take(shown).map(|(p, _)| p.as_str()).collect();
1820	    let changed = displayed
1821	        .iter()
1822	        .filter(|p| file_changed(conn, root, p))
1823	        .count();
1824	    let stale = changed > 0;
1825	    let data_lines: Vec<String> = rows
1826	        .iter()
1827	        .take(shown)
1828	        .map(|(_, line)| line.clone())
1829	        .collect();
1830	    let mut out = vec![
1831	        "kg: complexity — static AST proxy, not cognitive complexity; not comparable to hotspots/file cyclomatic".to_string(),
1832	    ];
1833	    if stale {
1834	        out.push(format!(
1835	            "kg: {changed} of {} result files changed since build — run kg build",
1836	            displayed.len()
1837	        ));
1838	    }
1839	    out.extend(data_lines.iter().cloned());
1840	    if (total as usize) > shown {
1841	        out.push(format!("showing {shown} of {total}"));
1842	        eprintln!("[kg] capped at {shown} results ({total} total)");
1843	    }
1844	    let built_at = db::meta_get(conn, "built_at")
1845	        .and_then(|v| v.parse().ok())
1846	        .unwrap_or(0);
1847	    let source_rev = db::meta_get(conn, "source_rev").unwrap_or_default();
1848	    crate::journal::record_payload(
1849	        path.unwrap_or("complexity"),
1850	        &data_lines,
1851	        stale,
1852	        shown,
1853	        total as usize,
1854	        built_at,
1855	        &source_rev,
1856	    );
1857	    crate::journal::record_result(total as usize, shown, total as usize, stale, 0);
1858	    Ok(out)
1859	}
