1861	/// `kg resolve --stdin` (Amendment 19): batch name resolution with per-name
1862	/// found/ambiguous/missing lines and a CLI exit code (0/1/2).
1863	pub fn resolve_names(conn: &Connection, names: &[String]) -> Result<(Vec<String>, i32)> {
1864	    let mut out = Vec::new();
1865	    let mut exit = 0;
1866	    for name in names {
1867	        let name = name.trim();
1868	        if name.is_empty() || name.starts_with('#') {
1869	            continue;
1870	        }
1871	        let (ids, cands) = target_ids(conn, name)?;
1872	        if ids.is_empty() {
1873	            out.push(format!("missing {name}"));
1874	            exit = exit.max(1);
1875	        } else if ids.len() > 1 {
1876	            for (path, line, qualname) in cands.iter().take(MAX_AMBIGUOUS_CANDIDATES) {
1877	                out.push(format!("ambiguous {name} {path}:{line} {qualname}"));
1878	            }
1879	            if ids.len() > cands.len() {
1880	                out.push(format!(
1881	                    "showing {} of {} candidates",
1882	                    cands.len(),
1883	                    ids.len()
1884	                ));
1885	            }
1886	            exit = 2;
1887	        } else if let Some((path, line, qualname)) = cands.first() {
1888	            out.push(format!("found {name} {path}:{line} {qualname}"));
1889	        }
1890	    }
1891	    Ok((out, exit))
1892	}
