1894	/// `kg files` (Amendment 19): indexed file inventory, build-time values.
1895	pub fn files(conn: &Connection, path: Option<&str>, limit: usize) -> Result<Vec<String>> {
1896	    let limit = clamp_limit(limit)?;
1897	    if let Some(p) = path {
1898	        validate_path_scope(p, false)?;
1899	    }
1900	    let scope = path.map(|p| p.trim_start_matches("./").trim_end_matches('/'));
1901	    let mut sql = String::from(
1902	        "SELECT f.path, COUNT(s.id), f.size, f.generated
1903	         FROM files f LEFT JOIN symbols s ON s.file_id = f.id",
1904	    );
1905	    let mut params: Vec<String> = Vec::new();
1906	    if let Some(scope) = scope {
1907	        sql.push_str(" WHERE (f.path = ?1 OR substr(f.path, 1, length(?1) + 1) = ?1 || '/')");
1908	        params.push(scope.to_string());
1909	    }
1910	    let total: usize = if let Some(scope) = scope {
1911	        conn.query_row(
1912	            "SELECT COUNT(*) FROM files f WHERE f.path = ?1 OR substr(f.path, 1, length(?1) + 1) = ?1 || '/'",
1913	            [scope],
1914	            |r| r.get::<_, i64>(0),
1915	        )? as usize
1916	    } else {
1917	        conn.query_row("SELECT COUNT(*) FROM files", [], |r| r.get::<_, i64>(0))? as usize
1918	    };
1919	    sql.push_str(&format!(" GROUP BY f.id ORDER BY f.path LIMIT {limit}"));
1920	    let mut stmt = conn.prepare(&sql)?;
1921	    let rows: Vec<(String, i64, i64, i64)> = if params.is_empty() {
1922	        stmt.query_map([], |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?)))?
1923	            .collect::<std::result::Result<_, _>>()?
1924	    } else {
1925	        stmt.query_map([&params[0]], |r| {
1926	            Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?))
1927	        })?
1928	        .collect::<std::result::Result<_, _>>()?
1929	    };
1930	    let files_caveat = "kg: files — build-time inventory; files created after the build are absent";
1931	    if rows.is_empty() {
1932	        return Err(KgError::NoResultsCaveated {
1933	            caveat: files_caveat,
1934	            detail: match scope {
1935	                Some(s) => format!("0 indexed files in '{s}'"),
1936	                None => "0 indexed files".to_string(),
1937	            },
1938	        });
1939	    }
1940	    let shown = rows.len();
1941	    let mut out = vec![files_caveat.to_string()];
1942	    out.extend(rows.into_iter().map(|(path, syms, bytes, gen)| {
1943	        format!("{path} symbols={syms} bytes={bytes} generated={gen}")
1944	    }));
1945	    if total > shown {
1946	        out.push(format!("showing {shown} of {total}"));
1947	        eprintln!("[kg] capped at {shown} results ({total} total)");
1948	    }
1949	    crate::journal::record_result(total, shown, total, false, 0);
1950	    Ok(out)
1951	}
