1953	/// `kg api` (Amendment 19): exported/public symbol inventory for a file or
1954	/// directory. Visibility is a static name heuristic in v1.
1955	pub fn api(
1956	    conn: &Connection,
1957	    root: &Path,
1958	    path: &str,
1959	    include_private: bool,
1960	    exclude_generated: bool,
1961	    limit: usize,
1962	) -> Result<Vec<String>> {
1963	    let limit = clamp_limit(limit)?;
1964	    let rel = path
1965	        .trim_start_matches("./")
1966	        .trim_end_matches('/')
1967	        .to_string();
1968	    validate_path_scope(&rel, false)?;
1969	    let root_scope = false;
1970	    let mut where_sql = String::from("s.kind IN ('function','method','class','trait','interface')");
1971	    if !root_scope {
1972	        where_sql.push_str(" AND (f.path = ?1 OR substr(f.path, 1, length(?1) + 1) = ?1 || '/')");
1973	    }
1974	    if !include_private {
1975	        where_sql.push_str(" AND s.exported = 1");
1976	    }
1977	    if exclude_generated {
1978	        where_sql.push_str(" AND s.file_id NOT IN (SELECT id FROM files WHERE generated = 1)");
1979	    }
1980	    let total: usize = if root_scope {
1981	        conn.query_row(
1982	            &format!(
1983	                "SELECT COUNT(*) FROM symbols s JOIN files f ON f.id = s.file_id WHERE {where_sql}"
1984	            ),
1985	            [],
1986	            |r| r.get::<_, i64>(0),
1987	        )? as usize
1988	    } else {
1989	        conn.query_row(
1990	            &format!(
1991	                "SELECT COUNT(*) FROM symbols s JOIN files f ON f.id = s.file_id WHERE {where_sql}"
1992	            ),
1993	            [&rel],
1994	            |r| r.get::<_, i64>(0),
1995	        )? as usize
1996	    };
1997	    if total == 0 {
1998	        return Err(KgError::NoResultsCaveated {
1999	            caveat: "kg: api — static export heuristics; re-exports, module visibility, and dynamic exports may be incomplete",
2000	            detail: format!("0 exported symbols in '{path}'"),
2001	        });
2002	    }
2003	    let sql = format!(
2004	        "SELECT f.path, s.line_start, s.kind, s.qualname, s.signature
2005	         FROM symbols s JOIN files f ON f.id = s.file_id
2006	         WHERE {where_sql}
2007	         ORDER BY f.path, s.line_start, s.qualname LIMIT {limit}"
2008	    );
2009	    let mut stmt = conn.prepare(&sql)?;
2010	    let map_row = |r: &rusqlite::Row<'_>| {
2011	        let mut text = format!(
2012	            "{}:{} {} {}",
2013	            r.get::<_, String>(0)?,
2014	            r.get::<_, i64>(1)?,
2015	            r.get::<_, String>(2)?,
2016	            r.get::<_, String>(3)?
2017	        );
2018	        let sig: String = r.get(4)?;
2019	        if !sig.is_empty() {
2020	            text.push(' ');
2021	            text.push_str(&sig);
2022	        }
2023	        Ok(text)
2024	    };
2025	    let rows: Vec<String> = if root_scope {
2026	        stmt.query_map([], map_row)?
2027	            .collect::<std::result::Result<_, _>>()?
2028	    } else {
2029	        stmt.query_map([&rel], map_row)?
2030	            .collect::<std::result::Result<_, _>>()?
2031	    };
2032	    let shown = rows.len();
2033	    let stale = rows.iter().take(shown).any(|line| {
2034	        line.split(':')
2035	            .next()
2036	            .is_some_and(|p| file_changed(conn, root, p))
2037	    });
2038	    let mut out = vec![
2039	        "kg: api — static export heuristics; re-exports, module visibility, and dynamic exports may be incomplete".to_string(),
2040	    ];
2041	    if stale {
2042	        out.push("kg: result files changed since build — run kg build".to_string());
2043	    }
2044	    let data_lines: Vec<String> = rows.iter().take(shown).cloned().collect();
2045	    out.extend(data_lines.iter().cloned());
2046	    if total > shown {
2047	        out.push(format!("showing {shown} of {total}"));
2048	        eprintln!("[kg] capped at {shown} results ({total} total)");
2049	    }
2050	    let built_at = db::meta_get(conn, "built_at")
2051	        .and_then(|v| v.parse().ok())
2052	        .unwrap_or(0);
2053	    let source_rev = db::meta_get(conn, "source_rev").unwrap_or_default();
2054	    crate::journal::record_payload(
2055	        path,
2056	        &data_lines,
2057	        stale,
2058	        shown,
2059	        total,
2060	        built_at,
2061	        &source_rev,
2062	    );
2063	    crate::journal::record_result(total, shown, total, stale, 0);
2064	    Ok(out)
2065	}
