2152	/// Unresolved-callee report (Amendment 5): files with counts, descending.
2153	/// Report shape — cap, no staleness; header carries the index total.
2154	pub fn unresolved(conn: &Connection, path: Option<&str>, limit: usize) -> Result<Vec<String>> {
2155	    let limit = clamp_limit(limit)?;
