2161	        &format!("SELECT COALESCE(SUM(unresolved), 0) FROM files f WHERE 1=1 {scope}"),
2162	        [],
2163	        |r| r.get(0),
2164	    )?;
2165	    if total == 0 {
2166	        return Err(KgError::NoResults(
2167	            "0 unresolved in indexed scope (external/builtin calls are not counted)".to_string(),
2168	        ));
2169	    }
2170	    let mut stmt = conn.prepare(&format!(
2171	        "SELECT f.path, f.unresolved FROM files f WHERE f.unresolved > 0 {scope}
2172	         ORDER BY f.unresolved DESC, f.path"
2173	    ))?;
2174	    let rows = stmt
2175	        .query_map([], |r| Ok((r.get::<_, String>(0)?, r.get::<_, i64>(1)?)))?
2176	        .collect::<std::result::Result<Vec<_>, _>>()?;

